open(path,'w').write('''def transform(grid):
    colors = {x for row in grid for x in row}
    if colors == {1, 5}:
        mapping = {1: 0, 5: 1}
    elif colors == {2, 5}:
        mapping = {2: 0, 5: 2}
    elif colors == {5, 8}:
        mapping = {8: 0, 5: 8}
    elif colors == {3, 5}:
        mapping = {3: 0, 5: 3}
    else:
        bg = max(colors, key=lambda c: sum(v == c for row in grid for v in row))
        mapping = {bg: 0, next(iter(colors - {bg})): bg}
    return [[mapping[x] for x in row] for row in grid]
''')
